content.content:
1	import { MATERIALS, evaluateImpact, generateCrackPattern } from './target.js';
2	import { YOYO_VARIANTS } from './yoyo.js';
3	
4	const { Engine, Bodies, Body, Composite, Constraint, Events, World } = Matter;
5	
6	let engine, world;
7	let yoyoBody = null;
8	let stringConstraint = null;
9	let targetBodies = [];
10	let fragmentBodies = [];
11	let groundBody, leftWall, rightWall;
12	let canvasW, canvasH;
13	
14	const eventListeners = {};
15	
16	export function on(event, fn) {
17	  if (!eventListeners[event]) eventListeners[event] = [];
18	  eventListeners[event].push(fn);
19	}
20	
21	function emit(event, data) {
22	  (eventListeners[event] || []).forEach(fn => fn(data));
23	}
24	
25	export function init(width, height) {
26	  canvasW = width;
27	  canvasH = height;
28	
29	  engine = Engine.create({
30	    gravity: { x: 0, y: 1.5 },
31	    positionIterations: 12,
32	    velocityIterations: 8,
33	  });
34	  world = engine.world;
35	
36	  groundBody = Bodies.rectangle(width / 2, height + 25, width * 3, 50, {
37	    isStatic: true, label: 'ground', friction: 0.6, restitution: 0.2,
38	  });
39	  leftWall = Bodies.rectangle(-25, height / 2, 50, height * 2, { isStatic: true, label: 'wall' });
40	  rightWall = Bodies.rectangle(width + 25, height / 2, 50, height * 2, { isStatic: true, label: 'wall' });
41	  Composite.add(world, [groundBody, leftWall, rightWall]);
42	
43	  Events.on(engine, 'collisionStart', onCollision);
44	}
45	
46	function onCollision(event) {
47	  for (const pair of event.pairs) {
48	    const { bodyA, bodyB } = pair;
49	    const isYoyoA = bodyA.label === 'yoyo';
50	    const isYoyoB = bodyB.label === 'yoyo';
51	    const isTargetA = bodyA.label === 'target';
52	    const isTargetB = bodyB.label === 'target';
53	
54	    if ((isYoyoA && isTargetB) || (isYoyoB && isTargetA)) {
55	      const target = isTargetA ? bodyA : bodyB;
56	      const yoyo = isYoyoA ? bodyA : bodyB;
57	      const speed = Math.sqrt(yoyo.velocity.x ** 2 + yoyo.velocity.y ** 2);
58	      const material = MATERIALS[target.plugin.materialKey];
59	      const impactMultiplier = yoyo.plugin.impactMultiplier;
60	
61	      const normal = pair.collision?.normal;
62	      let angleFactor = 1.0;
63	      if (speed > 0 && normal) {
64	        const dot = Math.abs((yoyo.velocity.x * normal.x + yoyo.velocity.y * normal.y) / speed);
65	        angleFactor = 0.3 + 0.7 * dot;
66	      }
67	
68	      const outcome = evaluateImpact(speed * angleFactor, yoyo.mass, material, impactMultiplier);
69	      emit('yoyo-hit-target', {
70	        target,
71	        yoyo,
72	        outcome,
73	        speed,
74	        angleFactor,
75	        hitPoint: { x: (bodyA.position.x + bodyB.position.x) / 2, y: (bodyA.position.y + bodyB.position.y) / 2 },
76	        material,
77	      });
78	    }
79	  }
80	}
81	
82	export function step(delta) {
83	  Engine.update(engine, delta);
84	}
85	
86	export function spawnYoyo(x, y, variantKey, asStatic = false) {
87	  if (yoyoBody) Composite.remove(world, yoyoBody);
88	  const v = YOYO_VARIANTS[variantKey];
89	  yoyoBody = Bodies.circle(x, y, v.radius, {
90	    label: 'yoyo',
91	    restitution: v.restitution,
92	    friction: v.friction,
93	    frictionAir: v.frictionAir,
94	    collisionFilter: { category: 0x0001, mask: 0x0002 | 0x0004 },
95	    plugin: { impactMultiplier: v.impactMultiplier, variantKey, radius: v.radius, fragmentsSpawned: false },
96	  });
97	  Body.setMass(yoyoBody, v.mass);
98	  if (asStatic) Body.setStatic(yoyoBody, true);
99	  Composite.add(world, yoyoBody);
100	  return yoyoBody;
101	}
102	
103	export function attachString(pivotX, pivotY, length, stiffness = 1.0) {
104	  if (stringConstraint) Composite.remove(world, stringConstraint);
105	  stringConstraint = Constraint.create({
106	    pointA: { x: pivotX, y: pivotY },
107	    bodyB: yoyoBody,
108	    pointB: { x: 0, y: 0 },
109	    length,
110	    stiffness,
111	    damping: 0.0,
112	  });
113	  Composite.add(world, stringConstraint);
114	}
115	
116	let pendingRelease = false;
117	let releaseVx = 0, releaseVy = 0;
118	
119	export function scheduleRelease(vx, vy) {
120	  pendingRelease = true;
121	  releaseVx = vx;
122	  releaseVy = vy;
123	}
124	
125	export function installReleaseHook() {
126	  Events.on(engine, 'beforeUpdate', () => {
127	    if (!pendingRelease) return;
128	    pendingRelease = false;
129	    if (stringConstraint) {
130	      Composite.remove(world, stringConstraint);
131	      stringConstraint = null;
132	    }
133	    if (yoyoBody) {
