2	
3	let pivot = { x: 0, y: 0 };
4	let stringLength = 130;
5	let variantKey = 'standard';
6	
7	let mouseX = 0, mouseY = 0;
8	let prevAngle = null;
9	let prevTime = null;
10	let smoothedAV = 0;   // radians/second, signed
11	let currAngle = 0;
12	
13	let mouseDown = false;
14	let canvas = null;
15	
16	let inputMode = 'swing'; // 'swing' | 'push'
17	
18	const callbacks = { swing: null, release: null, pivotMove: null };
19	
20	export function init(canvasEl, pivotPos, strLen, variant, mode = 'swing') {
21	  canvas = canvasEl;
22	  pivot = { ...pivotPos };
23	  stringLength = strLen;
24	  variantKey = variant;
25	  inputMode = mode;
26	  smoothedAV = 0;
27	  mouseDown = false;
28	  prevAngle = null;
29	  prevTime = null;
30	  currAngle = Math.PI / 2; // start below pivot
31	}
32	
33	export function setPivot(p) { pivot = { ...p }; }
34	export function setStringLength(l) { stringLength = l; }
35	
36	export function onSwing(fn) { callbacks.swing = fn; }
37	export function onRelease(fn) { callbacks.release = fn; }
38	export function onPivotMove(fn) { callbacks.pivotMove = fn; }
39	
40	export function attachToCanvas(canvasEl) {
41	  canvas = canvasEl;
42	  canvas.addEventListener('mousemove', onMouseMove);
43	  canvas.addEventListener('mousedown', onMouseDown);
44	  canvas.addEventListener('mouseup', onMouseUp);
45	  canvas.addEventListener('mouseleave', onMouseUp);
46	}
47	
48	export function detachFromCanvas() {
49	  if (!canvas) return;
50	  canvas.removeEventListener('mousemove', onMouseMove);
51	  canvas.removeEventListener('mousedown', onMouseDown);
52	  canvas.removeEventListener('mouseup', onMouseUp);
53	  canvas.removeEventListener('mouseleave', onMouseUp);
54	}
55	
56	function getCanvasXY(e) {
57	  const rect = canvas.getBoundingClientRect();
58	  return {
59	    x: (e.clientX - rect.left) * (canvas.width / rect.width),
60	    y: (e.clientY - rect.top) * (canvas.height / rect.height),
61	  };
62	}
63	
64	function onMouseDown(e) {
65	  mouseDown = true;
66	  const pos = getCanvasXY(e);
67	  mouseX = pos.x;
68	  mouseY = pos.y;
69	  prevTime = performance.now();
70	
71	  if (inputMode === 'push') {
72	    if (callbacks.pivotMove) callbacks.pivotMove({ x: pos.x, y: pos.y });
73	    return;
74	  }
75	
76	  currAngle = Math.atan2(mouseY - pivot.y, mouseX - pivot.x);
77	  prevAngle = currAngle;
78	  smoothedAV = 0;
79	}
80	
81	function onMouseMove(e) {
82	  const pos = getCanvasXY(e);
83	
84	  // Push mode: pivot always follows mouse, no hold required
85	  if (inputMode === 'push') {
86	    mouseX = pos.x;
87	    mouseY = pos.y;
88	    if (callbacks.pivotMove) callbacks.pivotMove({ x: pos.x, y: pos.y });
89	    return;
90	  }
91	
92	  if (!mouseDown) {
93	    mouseX = pos.x;
94	    mouseY = pos.y;
95	    return;
