content.content:
1	import { YOYO_VARIANTS } from './yoyo.js';
2	import { MATERIALS } from './target.js';
3	import * as Particles from './particles.js';
4	
5	let canvas, ctx;
6	let canvasW, canvasH;
7	
8	// Trail ring buffer
9	const TRAIL_MAX = 30;
10	const trail = [];
11	let spinAngle = 0;
12	
13	// Per-level render caches (invalidated when level identity changes)
14	let cachedGradient = null;
15	let cachedGradientKey = '';
16	let cachedGroundCanvas = null;
17	let cachedGroundKey = '';
18	
19	export function init(canvasEl) {
20	  canvas = canvasEl;
21	  ctx = canvas.getContext('2d');
22	  canvasW = canvas.width;
23	  canvasH = canvas.height;
24	}
25	
26	export function resize(w, h) {
27	  canvasW = w;
28	  canvasH = h;
29	}
30	
31	export function updateTrail(x, y) {
32	  trail.push({ x, y });
33	  if (trail.length > TRAIL_MAX) trail.shift();
34	}
35	
36	export function clearTrail() { trail.length = 0; }
37	
38	export function updateSpin(angularVelocity, dt) {
39	  spinAngle += angularVelocity * dt;
40	}
41	
42	export function draw({
43	  state,
44	  mode = 'swing',
45	  level,
46	  pivot,
47	  yoyoBody,
48	  targetBodies,
49	  fragmentBodies,
50	  stringConstraint,
51	  angularSpeed,
52	  aimPoints,
53	  hpFraction = 1.0,
54	  hitCount = 0,
55	  comboCount = 0,
56	  hitLabel = null,
57	  shake = 0,
58	}) {
59	  ctx.clearRect(0, 0, canvasW, canvasH);
60	  ctx.save();
61	  if (shake > 0) {
62	    ctx.translate(
63	      (Math.random() - 0.5) * 2 * shake,
64	      (Math.random() - 0.5) * 2 * shake
65	    );
66	  }
67	
68	  drawBackground(level);
69	  drawGround(level);
70	
71	  if (stringConstraint && (state === 'SWINGING' || state === 'IDLE_ARMED')) {
72	    drawString(pivot, yoyoBody, angularSpeed, stringConstraint);
73	  }
74	
75	  drawTrail(yoyoBody, level);
76	  drawFragments(fragmentBodies);
77	  drawTargets(targetBodies);
78	
79	  if (yoyoBody) {
80	    const v = YOYO_VARIANTS[yoyoBody.plugin?.variantKey || 'standard'];
81	    drawYoyo(yoyoBody, v);
82	  }
83	
84	  if (aimPoints && aimPoints.length > 1) drawAimGuide(aimPoints);
85	
86	  Particles.draw(ctx);
87	
88	  drawSpeedMeter(angularSpeed);
89	  if (mode === 'swing' || stringConstraint) drawPivotHand(pivot, state);
90	  if (mode === 'push') {
91	    drawHpBar(hpFraction);
92	    drawHitCounter(hitCount);
93	    drawCombo(comboCount);
94	  }
95	  if (hitLabel && hitLabel.alpha > 0) drawHitLabel(hitLabel);
96	  ctx.restore();
97	}
98	
99	function drawBackground(level) {
100	  const key = level.background[0] + '|' + level.background[1];
101	  if (!cachedGradient || cachedGradientKey !== key) {
102	    cachedGradient = ctx.createLinearGradient(0, 0, 0, canvasH);
103	    cachedGradient.addColorStop(0, level.background[0]);
104	    cachedGradient.addColorStop(1, level.background[1]);
105	    cachedGradientKey = key;
106	  }
107	  ctx.fillStyle = cachedGradient;
108	  ctx.fillRect(0, 0, canvasW, canvasH);
109	}
110	
111	function drawGround(level) {
112	  const key = level.groundColor + '|' + canvasW;
113	  if (!cachedGroundCanvas || cachedGroundKey !== key) {
114	    const GRASS_MAX = 9, GROUND_H = 40;
115	    const oc = document.createElement('canvas');
116	    oc.width = canvasW;
117	    oc.height = GRASS_MAX + GROUND_H;
118	    const gctx = oc.getContext('2d');
119	
120	    gctx.fillStyle = level.groundColor;
121	    gctx.fillRect(0, GRASS_MAX, canvasW, GROUND_H);
122	
123	    gctx.strokeStyle = 'rgba(0,0,0,0.5)';
124	    gctx.lineWidth = 3;
125	    gctx.beginPath();
126	    gctx.moveTo(0, GRASS_MAX);
127	    gctx.lineTo(canvasW, GRASS_MAX);
128	    gctx.stroke();
129	
130	    gctx.fillStyle = '#3a8f3a';
131	    for (let x = 10; x < canvasW; x += 22) {
132	      const h = 6 + Math.sin(x * 0.3) * 3;
133	      gctx.fillRect(x, GRASS_MAX - h, 4, h);
134	    }
135	
136	    cachedGroundCanvas = oc;
137	    cachedGroundKey = key;
138	  }
139	  ctx.drawImage(cachedGroundCanvas, 0, canvasH - 49);
140	}
141	
142	function drawString(pivot, yoyo, normalizedSpeed, constraint) {
143	  if (!yoyo) return;
144	  const px = pivot.x, py = pivot.y;
145	  const ex = yoyo.position.x, ey = yoyo.position.y;
146	
147	  const dx = ex - px;
148	  const dy = ey - py;
149	  const dist = Math.sqrt(dx * dx + dy * dy);
150	  if (dist < 1) return;
151	
152	  const perpX = -dy / dist;
153	  const perpY = dx / dist;
154	
155	  // Gravity sag: stronger when rope is horizontal, zero when vertical
156	  const horizontalFraction = Math.abs(dx) / dist;
157	  const gravSag = horizontalFraction * dist * 0.18;
158	
159	  // Extra sag when rope is slack (yoyo closer than constraint length)
160	  const slack = Math.max(0, (constraint?.length ?? dist) - dist);
161	  const slackSag = slack * 0.4;
162	
163	  const totalSag = gravSag + slackSag;
164	
165	  // Lateral bow from swing speed
166	  const speedBow = normalizedSpeed * 16;
167	
168	  // Build 8 rope points with parabolic gravity + speed bow
169	  const N = 8;
170	  const pts = [];
171	  for (let i = 0; i <= N; i++) {
172	    const t = i / N;
173	    const s = Math.sin(t * Math.PI); // 0 at ends, peak at midpoint
174	    pts.push({
175	      x: px + dx * t + perpX * speedBow * s,
176	      y: py + dy * t + perpY * speedBow * s + totalSag * s,
177	    });
178	  }
179	
180	  // Draw smooth curve through points (Catmull-Rom style via quadratic beziers)
181	  ctx.shadowColor = 'rgba(0,0,0,0.25)';
182	  ctx.shadowBlur = 3;
183	  ctx.strokeStyle = '#3d2b1f';
184	  ctx.lineWidth = 2.5;
185	  ctx.lineCap = 'round';
186	  ctx.lineJoin = 'round';
187	  ctx.beginPath();
188	  ctx.moveTo(pts[0].x, pts[0].y);
189	  for (let i = 1; i < pts.length - 1; i++) {
190	    const mx = (pts[i].x + pts[i + 1].x) / 2;
191	    const my = (pts[i].y + pts[i + 1].y) / 2;
192	    ctx.quadraticCurveTo(pts[i].x, pts[i].y, mx, my);
193	  }
194	  ctx.lineTo(pts[pts.length - 1].x, pts[pts.length - 1].y);
195	  ctx.stroke();
196	  ctx.shadowBlur = 0;
197	}
198	
199	function drawTrail(yoyo, level) {
200	  if (!yoyo || trail.length < 2) return;
201	  const v = YOYO_VARIANTS[yoyo.plugin?.variantKey || 'standard'];
202	  for (let i = 1; i < trail.length; i++) {
203	    const alpha = (i / trail.length) * 0.45;
204	    const r = v.radius * (i / trail.length) * 0.7;
205	    ctx.beginPath();
206	    ctx.arc(trail[i].x, trail[i].y, Math.max(1, r), 0, Math.PI * 2);
207	    ctx.fillStyle = v.trailColor + alpha + ')';
208	    ctx.fill();
209	  }
210	}
211	
212	function drawYoyo(body, variant) {
213	  const { x, y } = body.position;
214	  ctx.save();
215	  ctx.translate(x, y);
216	  ctx.rotate(spinAngle);
217	
218	  // drop shadow
219	  ctx.shadowColor = 'rgba(0,0,0,0.4)';
220	  ctx.shadowBlur = 10;
221	  ctx.shadowOffsetY = 4;
222	
223	  // outer circle fill
224	  ctx.beginPath();
225	  ctx.arc(0, 0, variant.radius, 0, Math.PI * 2);
226	  ctx.fillStyle = variant.color;
227	  ctx.fill();
228	
229	  // outer ring outline (cartoon)
230	  ctx.shadowBlur = 0;
231	  ctx.shadowOffsetY = 0;
232	  ctx.strokeStyle = variant.outlineColor;
233	  ctx.lineWidth = 3.5;
234	  ctx.stroke();
235	
236	  // inner groove ring
237	  ctx.beginPath();
238	  ctx.arc(0, 0, variant.radius * 0.65, 0, Math.PI * 2);
239	  ctx.strokeStyle = 'rgba(0,0,0,0.25)';
240	  ctx.lineWidth = 2;
241	  ctx.stroke();
242	
243	  // axle dot
244	  ctx.beginPath();
245	  ctx.arc(0, 0, variant.radius * 0.28, 0, Math.PI * 2);
246	  ctx.fillStyle = variant.trimColor;
247	  ctx.fill();
248	  ctx.strokeStyle = 'rgba(0,0,0,0.3)';
249	  ctx.lineWidth = 1.5;
250	  ctx.stroke();
251	
252	  // spin marker
253	  ctx.beginPath();
254	  ctx.moveTo(variant.radius * 0.28, 0);
255	  ctx.lineTo(variant.radius * 0.88, 0);
256	  ctx.strokeStyle = 'rgba(0,0,0,0.35)';
257	  ctx.lineWidth = 2;
258	  ctx.stroke();
259	
260	  // crack overlay when damaged
261	  if (body.plugin?.cracked && body.plugin?.crackPattern) {
262	    ctx.strokeStyle = 'rgba(0,0,0,0.65)';
263	    ctx.lineWidth = 1.5;
264	    for (const { angle, len } of body.plugin.crackPattern) {
265	      ctx.beginPath();
266	      ctx.moveTo(0, 0);
267	      ctx.lineTo(Math.cos(angle) * len * variant.radius * 1.8, Math.sin(angle) * len * variant.radius * 1.8);
268	      ctx.stroke();
269	    }
270	  }
271	
272	  ctx.restore();
273	}
274	
275	function drawTargets(targets) {
276	  for (const body of targets) {
277	    const mat = MATERIALS[body.plugin.materialKey];
278	    drawPhysicsBody(body, body.plugin.cracked ? mat.crackedColor : mat.color, mat.outlineColor);
279	    if (body.plugin.cracked && body.plugin.crackPattern) drawCracks(body, body.plugin.crackPattern);
280	
281	    // material label
282	    const { x, y } = body.position;
283	    ctx.fillStyle = 'rgba(0,0,0,0.5)';
284	    ctx.font = 'bold 11px system-ui';
285	    ctx.textAlign = 'center';
286	    ctx.fillText(mat.label, x, y + 4);
287	
288	    // glow
289	    ctx.save();
290	    ctx.globalAlpha = 0.18;
291	    ctx.beginPath();
292	    const verts = body.vertices;
293	    ctx.moveTo(verts[0].x, verts[0].y);
294	    for (let i = 1; i < verts.length; i++) ctx.lineTo(verts[i].x, verts[i].y);
295	    ctx.closePath();
296	    ctx.fillStyle = mat.glowColor;
297	    ctx.fill();
298	    ctx.restore();
299	
300	  }
301	}
302	
303	function drawCracks(body, pattern) {
304	  const { x, y } = body.position;
305	  const w = body.plugin.width;
306	  const h = body.plugin.height;
307	  const maxR = Math.min(w, h) * 0.45;
308	  ctx.save();
309	  ctx.translate(x, y);
