  ctx.fillStyle = variant.color;
  ctx.fill();
  ctx.shadowBlur = 0;
  ctx.shadowOffsetY = 0;
  ctx.strokeStyle = variant.outlineColor;
  ctx.lineWidth = 2.5;
  ctx.stroke();

  // Belly highlight
  ctx.beginPath();
  ctx.ellipse(r * 0.05, r * 0.14, r * 0.44, r * 0.27, 0, 0, Math.PI * 2);
  ctx.fillStyle = variant.trimColor;
  ctx.fill();

