    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(eyeX - xs, eyeY - xs); ctx.lineTo(eyeX + xs, eyeY + xs);
    ctx.moveTo(eyeX + xs, eyeY - xs); ctx.lineTo(eyeX - xs, eyeY + xs);
