    const woundPositions = [
      [-r * 0.35, -r * 0.18],
      [r * 0.06, r * 0.28],
      [-r * 0.52, r * 0.12],
      [r * 0.22, -r * 0.32],
    ];
    ctx.strokeStyle = '#cc2222';
    ctx.lineWidth = 1.8;
    ctx.lineCap = 'round';
    for (let i = 0; i < woundCount; i++) {
