// rat squeak on impact — pitch and duration scale with intensity
export function playHit(materialKey, intensity = 0.5) {
  const ac = ctx();

  // Squeak tone: triangle oscillator with quick pitch drop
  const pitch = 800 + intensity * 600;
  const osc = ac.createOscillator();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(pitch, ac.currentTime);
  osc.frequency.exponentialRampToValueAtTime(pitch * 0.45, ac.currentTime + 0.1);

  const gain = ac.createGain();
  gain.gain.setValueAtTime(0.3 + intensity * 0.28, ac.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.12);

  osc.connect(gain);
  gain.connect(ac.destination);
  osc.start();
  osc.stop(ac.currentTime + 0.13);

  // Impact thud — character varies by material hardness
  const thudFreq = { glass: 2200, wood: 650, steel: 280 }[materialKey] ?? 900;
  const thud = noise(0.07);
  const filter = ac.createBiquadFilter();
  filter.type = 'bandpass';
  filter.frequency.value = thudFreq;
  filter.Q.value = 3;
  const thudGain = ac.createGain();
  thudGain.gain.setValueAtTime(0.18 * intensity, ac.currentTime);
  thudGain.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.07);
  thud.connect(filter);
  filter.connect(thudGain);
  thudGain.connect(ac.destination);
  thud.start();
  thud.stop(ac.currentTime + 0.08);
}

// wet splat + dying squeal
export function playShatter() {
  const ac = ctx();

  // Meaty splat: broadband noise swept down
  const splat = noise(0.55);
  const lpf = ac.createBiquadFilter();
  lpf.type = 'lowpass';
  lpf.frequency.setValueAtTime(1200, ac.currentTime);
  lpf.frequency.exponentialRampToValueAtTime(120, ac.currentTime + 0.55);
  const splatGain = ac.createGain();
  splatGain.gain.setValueAtTime(1.1, ac.currentTime);
  splatGain.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.55);
  splat.connect(lpf);
  lpf.connect(splatGain);
  splatGain.connect(ac.destination);
  splat.start();
  splat.stop(ac.currentTime + 0.6);

  // Dying squeal: sawtooth sweeping from high to very low
  const squeal = ac.createOscillator();
  squeal.type = 'sawtooth';
  squeal.frequency.setValueAtTime(1600, ac.currentTime);
  squeal.frequency.exponentialRampToValueAtTime(80, ac.currentTime + 0.45);
  const squealGain = ac.createGain();
  squealGain.gain.setValueAtTime(0.35, ac.currentTime);
  squealGain.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.45);
  squeal.connect(squealGain);
  squealGain.connect(ac.destination);
  squeal.start();
  squeal.stop(ac.currentTime + 0.45);
}

// escalating squeaks per combo tier — square wave for a ratty bite
export function playComboTone(comboCount) {
  if (comboCount < 2) return;
  const ac = ctx();
  const freq = Math.min(380 * Math.pow(1.38, comboCount - 2), 2200);

  const osc = ac.createOscillator();
  osc.type = 'square';
  osc.frequency.setValueAtTime(freq, ac.currentTime);
  osc.frequency.exponentialRampToValueAtTime(freq * 0.7, ac.currentTime + 0.09);

  const gain = ac.createGain();
  gain.gain.setValueAtTime(0.1, ac.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.11);

  osc.connect(gain);
  gain.connect(ac.destination);
  osc.start();
  osc.stop(ac.currentTime + 0.12);
}

