1	import * as Physics from './physics.js';
2	import * as Input from './input.js';
3	import * as Renderer from './renderer.js';
4	import * as Particles from './particles.js';
5	import * as UI from './ui.js';
6	import { YOYO_VARIANTS } from './yoyo.js';
7	import { LEVELS, getLevel, saveProgress, loadProgress } from './levels.js';
8	import { generateCrackPattern } from './target.js';
9	import { playHit, playShatter, playComboTone } from './audio.js';
10	
11	const canvas = document.getElementById('game-canvas');
12	const CANVAS_W = 1100;
13	const CANVAS_H = 620;
14	canvas.width = CANVAS_W;
15	canvas.height = CANVAS_H;
16	
17	// --- State machine ---
18	// States: PICKER | IDLE_ARMED | SWINGING | RELEASED | IMPACT | RESULT
19	const YOYO_MAX_HP = 100;
20	
21	let gameState = 'PICKER';
22	let currentLevelId = 1;
23	let selectedVariant = 'standard';
24	let selectedMode = 'push'; // 'swing' | 'push' — synced from UI.getSelectedMode() on init
25	let yoyoHp = YOYO_MAX_HP;
26	let hitCount = 0;
27	let hitCooldown = 0;
28	let comboCount = 0;
29	let comboTimer = 0;
30	const COMBO_WINDOW = 1.0;
31	let hitLabel = { text: '', x: 0, y: 0, timer: 0, color: '#fff' };
32	const HIT_LABEL_DURATION = 0.7;
33	let shakeTimer = 0;
34	let shakeIntensity = 0;
35	const SHAKE_DURATION = 0.3;
36	let lastTime = null;
37	let pivot = { x: 0, y: 0 };
38	let stringLength = 130;
39	let lastOutcome = null;
40	let lastScore = 0;
41	let impactTimer = 0;
42	const AIM_GUIDE_DURATION = 0.35;
43	let aimGuideTimer = 0;
44	let aimPoints = null;
45	let spinAccum = 0; // accumulated spin angle for renderer
46	
47	function currentLevel() {
48	  return getLevel(currentLevelId);
49	}
50	
51	function computePivot(level) {
52	  return {
53	    x: level.pivot.x * CANVAS_W,
54	    y: level.pivot.y * CANVAS_H,
55	  };
56	}
57	
58	function calcScore(outcome, speed, material, angleFactor = 1.0) {
59	  const base = outcome === 'SHATTER' ? 1000 : outcome === 'CRACK' ? 300 : 0;
60	  const speedBonus = Math.floor(speed / 8);
61	  return Math.floor((base + speedBonus) * angleFactor);
62	}
63	
64	function calcPushScore(hits) {
65	  return Math.max(200, 3000 - (hits - 1) * 500);
66	}
67	
68	function computeAimPoints(vx, vy, x0, y0) {
69	  // Matter.js: gravity.y=1.5, gravity.scale=0.001, engine steps in ms
70	  // effective px/s^2 ≈ 1500
71	  const g = 1500;
72	  const pts = [];
73	  for (let i = 0; i < 22; i++) {
74	    const t = i * 0.025;
75	    pts.push({ x: x0 + vx * t, y: y0 + vy * t + 0.5 * g * t * t });
76	  }
77	  return pts;
78	}
79	
80	// --- Setup ---
81	Physics.init(CANVAS_W, CANVAS_H);
82	Physics.installReleaseHook();
83	Renderer.init(canvas);
84	UI.init();
85	selectedMode = UI.getSelectedMode();
86	
87	UI.onVariantChange(v => { selectedVariant = v; });
88	UI.onModeChange(m => { selectedMode = m; });
89	
90	UI.onStart(variant => {
91	  selectedVariant = variant;
92	  startLevel();
93	});
94	
95	UI.onRetry(() => {
96	  UI.hideResult();
97	  startLevel();
98	});
99	
100	UI.onLevelSelect(id => {
101	  currentLevelId = id;
102	  UI.hideLevelSelect();
103	  UI.showPicker();
104	});
105	
106	UI.onLevelSelectBack(() => {
107	  UI.hideResult();
108	  UI.buildLevelSelect(LEVELS, loadProgress());
109	  UI.showLevelSelect();
110	});
111	
112	UI.onNext(() => {
113	  UI.hideResult();
114	  const nextId = currentLevelId + 1;
115	  if (nextId <= LEVELS.length) {
116	    currentLevelId = nextId;
117	    startLevel();
118	  } else {
119	    currentLevelId = 1;
120	    startLevel();
121	  }
122	});
123	
124	// Physics collision event
125	Physics.on('yoyo-hit-target', ({ target, yoyo, outcome, speed, hitPoint, material, angleFactor }) => {
126	  const af = angleFactor ?? 1.0;
127	  const variant = YOYO_VARIANTS[yoyo.plugin?.variantKey || 'standard'];
128	
129	  if (selectedMode === 'push') {
130	    if (gameState !== 'SWINGING' || hitCooldown > 0) return;
131	
132	    const comboMultiplier = Math.min(1 + comboCount * 0.5, 3.0);
133	    comboCount++;
134	    comboTimer = COMBO_WINDOW;
135	
136	    const damage = speed * af * (material.yoyoDamage || 1.0) * (yoyo.plugin.impactMultiplier || 1.0) * comboMultiplier / 15;
137	    yoyoHp = Math.max(0, yoyoHp - damage);
138	    hitCount++;
139	    hitCooldown = 0.35;
140	    playHit(target.plugin.materialKey, Math.min(damage / YOYO_MAX_HP, 1));
141	    playComboTone(comboCount);
142	
143	    if (af < 0.55) {
144	      hitLabel = { text: 'GLANCING!', x: hitPoint.x, y: hitPoint.y, timer: HIT_LABEL_DURATION, color: '#f4a261' };
145	    } else if (af > 0.88) {
146	      hitLabel = { text: 'CLEAN HIT!', x: hitPoint.x, y: hitPoint.y, timer: HIT_LABEL_DURATION, color: '#80ffdb' };
147	    }
148	
149	    if (damage > 20) {
150	      shakeIntensity = Math.min(damage / 8, 10);
151	      shakeTimer = SHAKE_DURATION;
152	    }
153	
154	    // Progressive crack visuals
155	    const hpFrac = yoyoHp / YOYO_MAX_HP;
156	    yoyo.plugin.cracked = hpFrac < 1.0;
157	    const crackCount = hpFrac < 0.25 ? 12 : hpFrac < 0.5 ? 8 : hpFrac < 0.75 ? 4 : 0;
158	    if (crackCount > 0) yoyo.plugin.crackPattern = generateCrackPattern(crackCount);
159	
160	    Particles.emit(hitPoint.x, hitPoint.y, {
161	      count: 6,
162	      color: variant.color,
163	      speed: 180,
164	      radius: 3,
165	    });
166	
167	    if (yoyoHp <= 0) {
168	      gameState = 'IMPACT';
169	      lastOutcome = 'SHATTER';
170	      lastScore = calcPushScore(hitCount);
171	      playShatter();
172	      Physics.applyBreak(yoyo, 'SHATTER', hitPoint, variant.blastBonus);
173	      Particles.emit(hitPoint.x, hitPoint.y, { count: 20, color: variant.color, speed: 350, radius: 5 });
174	      impactTimer = 0.85;
175	    }
176	    return;
177	  }
178	
179	  // Fling mode
180	  if (gameState !== 'RELEASED') return;
181	  gameState = 'IMPACT';
182	  lastOutcome = outcome;
183	  lastScore = calcScore(outcome, speed, material, af);
184	  Physics.applyBreak(yoyo, outcome, hitPoint, variant.blastBonus);
185	
186	  const colors = { SHATTER: ['#a8d8ea','#fff','#90e0ef'], CRACK: ['#c4a265','#8b6914','#fff'], SURVIVE: ['#8a9ba8','#adb5bd'] };
187	  const count = outcome === 'SHATTER' ? 20 : outcome === 'CRACK' ? 10 : 5;
188	  Particles.emit(hitPoint.x, hitPoint.y, {
189	    count,
190	    color: (colors[outcome] || ['#fff'])[Math.floor(Math.random() * 3)],
191	    speed: outcome === 'SHATTER' ? 350 : 200,
192	    radius: outcome === 'SHATTER' ? 5 : 3,
193	  });
194	
195	  impactTimer = 0.85;
196	});
197	
198	// Input callbacks
199	Input.onSwing(({ x, y, angle, angularVelocity }) => {
200	  if (gameState !== 'SWINGING') return;
201	  Physics.setYoyoPosition(x, y);
202	  Physics.setYoyoVelocity(0, 0);
203	  Renderer.updateTrail(x, y);
204	  Renderer.updateSpin(angularVelocity, 1 / 60);
205	});
206	
207	Input.onPivotMove(({ x, y }) => {
208	  if (gameState !== 'SWINGING') return;
209	  Physics.updatePivot(x, y);
210	});
211	
212	Input.onRelease(({ vx, vy }) => {
213	  if (gameState !== 'SWINGING') return;
214	  gameState = 'RELEASED';
215	  Renderer.clearTrail();
216	  Input.detachFromCanvas();
217	
218	  const yoyoBody = Physics.getYoyoBody();
219	  if (yoyoBody) {
220	    aimPoints = computeAimPoints(vx, vy, yoyoBody.position.x, yoyoBody.position.y);
221	  }
222	  aimGuideTimer = AIM_GUIDE_DURATION;
223	  Physics.scheduleRelease(vx, vy);
224	});
225	
226	function startLevel() {
227	  const level = currentLevel();
228	  pivot = computePivot(level);
229	  stringLength = level.stringLength;
230	  spinAccum = 0;
231	
232	  yoyoHp = YOYO_MAX_HP;
233	  hitCount = 0;
234	  hitCooldown = 0;
235	  comboCount = 0;
236	  comboTimer = 0;
237	  hitLabel = { text: '', x: 0, y: 0, timer: 0, color: '#fff' };
238	  shakeTimer = 0;
239	  shakeIntensity = 0;
240	
241	  Physics.reset();
242	  Particles.clear();
243	  Renderer.clearTrail();
244	
245	  // Spawn targets
246	  Physics.spawnTargets(level.targets, level.pivot.x, level.pivot.y);
247	
248	  // Spawn yoyo and setup input based on mode
249	  if (selectedMode === 'push') {
250	    const psl = level.pushStringLength || stringLength;
251	    Physics.spawnYoyo(pivot.x, pivot.y + psl, selectedVariant);
252	    Physics.attachString(pivot.x, pivot.y, psl, 0.65);
253	    Input.init(canvas, pivot, psl, selectedVariant, 'push');
254	  } else {
255	    const startX = pivot.x;
256	    const startY = pivot.y + stringLength;
257	    Physics.spawnYoyo(startX, startY, selectedVariant);
258	    Physics.attachString(pivot.x, pivot.y, stringLength);
259	    Input.init(canvas, pivot, stringLength, selectedVariant, 'swing');
260	  }
261	  Input.attachToCanvas(canvas);
262	
263	  UI.hidePicker();
264	  if (selectedMode === 'push') {
265	    UI.setHint('Move the mouse to swing the rat! Chain hits for a combo bonus.');
266	  } else {
267	    UI.setHint(level.hint || 'Hold mouse button and move in circles to build speed!');
268	  }
269	
270	  gameState = 'SWINGING';
271	  lastOutcome = null;
272	  lastScore = 0;
273	  aimPoints = null;
274	  aimGuideTimer = 0;
275	  impactTimer = 0;
276	}
277	
278	// --- Game Loop ---
279	function gameLoop(timestamp) {
280	  requestAnimationFrame(gameLoop);
281	
282	  if (lastTime === null) { lastTime = timestamp; return; }
283	  const dt = Math.min((timestamp - lastTime) / 1000, 0.05);
284	  lastTime = timestamp;
285	
286	  // Physics step (all states except PICKER/RESULT where physics needn't run)
287	  if (gameState !== 'PICKER' && gameState !== 'RESULT') {
288	    Physics.step(dt * 1000);
289	    Particles.update(dt);
290	    if (hitCooldown > 0) hitCooldown -= dt;
291	    if (comboTimer > 0) {
292	      comboTimer -= dt;
293	      if (comboTimer <= 0) comboCount = 0;
294	    }
295	    if (hitLabel.timer > 0) hitLabel.timer -= dt;
296	    if (shakeTimer > 0) shakeTimer -= dt;
297	  }
298	
299	  // State-specific logic
300	  if (gameState === 'RELEASED') {
301	    aimGuideTimer -= dt;
302	    if (aimGuideTimer <= 0) aimPoints = null;
303	
304	    // Keep yoyo within bounds (cap speed to avoid tunneling)
305	    const yoyo = Physics.getYoyoBody();
306	    if (yoyo) {
307	      Physics.clampYoyoSpeed(YOYO_VARIANTS[selectedVariant].maxSpeed);
308	      Renderer.updateTrail(yoyo.position.x, yoyo.position.y);
309	
310	      // Off-screen without hitting anything → RESULT with survive
311	      if (yoyo.position.x < -100 || yoyo.position.x > CANVAS_W + 100 ||
312	          yoyo.position.y > CANVAS_H + 100) {
313	        gameState = 'RESULT';
314	        lastOutcome = 'SURVIVE';
315	        lastScore = 0;
316	        showResult();
317	      }
318	    }
319	  }
320	
321	  if (gameState === 'IMPACT') {
322	    impactTimer -= dt;
323	    if (impactTimer <= 0) {
324	      gameState = 'RESULT';
325	      showResult();
326	    }
327	  }
328	
329	  // Push mode: update trail and spin from physics body during swing
330	  if (selectedMode === 'push' && gameState === 'SWINGING') {
331	    const yb = Physics.getYoyoBody();
332	    if (yb) {
333	      Renderer.updateTrail(yb.position.x, yb.position.y);
334	      Renderer.updateSpin(yb.angularVelocity * 60, 1 / 60);
335	    }
336	  }
337	
338	  // Render
339	  const level = currentLevel();
340	  let angularSpeed = 0;
341	  if (gameState === 'SWINGING') {
342	    if (selectedMode === 'push') {
343	      const yb = Physics.getYoyoBody();
344	      if (yb) {
345	        const spd = Math.sqrt(yb.velocity.x ** 2 + yb.velocity.y ** 2);
346	        angularSpeed = Math.min(spd / YOYO_VARIANTS[selectedVariant].pushMaxSpeed, 1);
347	      }
348	    } else {
349	      angularSpeed = Input.getAngularSpeed();
350	    }
351	  }
352	
353	  // In push mode, pass the constraint anchor as pivot so string + hand draw at mouse position
354	  const constraint = Physics.getStringConstraint();
355	  const displayPivot = (selectedMode === 'push' && constraint) ? constraint.pointA : pivot;
356	
357	  Renderer.draw({
358	    state: gameState,
359	    mode: selectedMode,
360	    level,
361	    pivot: displayPivot,
362	    yoyoBody: Physics.getYoyoBody(),
363	    targetBodies: Physics.getTargetBodies(),
364	    fragmentBodies: Physics.getFragmentBodies(),
365	    stringConstraint: constraint,
366	    angularSpeed,
367	    aimPoints: aimGuideTimer > 0 ? aimPoints : null,
368	    hpFraction: yoyoHp / YOYO_MAX_HP,
369	    hitCount,
370	    comboCount,
371	    hitLabel: { ...hitLabel, alpha: hitLabel.timer / HIT_LABEL_DURATION },
372	    shake: shakeTimer > 0 ? shakeIntensity * (shakeTimer / SHAKE_DURATION) : 0,
373	  });
374	}
375	
376	function showResult() {
377	  Renderer.clearTrail();
378	  Input.detachFromCanvas();
379	  Physics.removeYoyo();
380	
381	  const level = currentLevel();
382	  saveProgress(currentLevelId, lastScore);
383	
384	  const parScore = selectedMode === 'push' ? (level.pushParScore || 1500) : level.parScore;
385	  UI.showResult(lastOutcome, lastScore, parScore);
386	  UI.setNextVisible(currentLevelId < LEVELS.length);
387	  UI.setHint('');
388	}
389	
390	// Initial state
391	UI.buildLevelSelect(LEVELS, loadProgress());
392	UI.showLevelSelect();
393	UI.setHint('');
394	requestAnimationFrame(gameLoop);
395

