1	import { YOYO_VARIANTS } from './yoyo.js';
2	import { MATERIALS } from './target.js';
3	import * as Particles from './particles.js';
4	
5	let canvas, ctx;
6	let canvasW, canvasH;
7	
8	// Trail ring buffer
9	const TRAIL_MAX = 30;
10	const trail = [];
11	let spinAngle = 0;
12	
13	// Per-level render caches (invalidated when level identity changes)
14	let cachedGradient = null;
15	let cachedGradientKey = '';
16	let cachedGroundCanvas = null;
17	let cachedGroundKey = '';
18	
19	export function init(canvasEl) {
20	  canvas = canvasEl;
21	  ctx = canvas.getContext('2d');
22	  canvasW = canvas.width;
23	  canvasH = canvas.height;
24	}
25	
26	export function resize(w, h) {
27	  canvasW = w;
28	  canvasH = h;
29	}
30	
31	export function updateTrail(x, y) {
32	  trail.push({ x, y });
33	  if (trail.length > TRAIL_MAX) trail.shift();
34	}
35	
36	export function clearTrail() { trail.length = 0; }
37	
38	export function updateSpin(angularVelocity, dt) {
39	  spinAngle += angularVelocity * dt;
40	}
41	
42	export function draw({
43	  state,
44	  mode = 'swing',
45	  level,
46	  pivot,
47	  yoyoBody,
48	  targetBodies,
49	  fragmentBodies,
50	  stringConstraint,
51	  angularSpeed,
52	  aimPoints,
53	  hpFraction = 1.0,
54	  hitCount = 0,
55	  comboCount = 0,
56	  hitLabel = null,
57	  shake = 0,
58	}) {
59	  ctx.clearRect(0, 0, canvasW, canvasH);
60	  ctx.save();
61	  if (shake > 0) {
62	    ctx.translate(
63	      (Math.random() - 0.5) * 2 * shake,
64	      (Math.random() - 0.5) * 2 * shake
65	    );
66	  }
67	
68	  drawBackground(level);
69	  drawGround(level);
70	
71	  if (stringConstraint && (state === 'SWINGING' || state === 'IDLE_ARMED')) {
72	    drawString(pivot, yoyoBody, angularSpeed, stringConstraint);
73	  }
74	
75	  drawTrail(yoyoBody, level);
76	  drawFragments(fragmentBodies);
77	  drawTargets(targetBodies);
78	
79	  if (yoyoBody) {
80	    const v = YOYO_VARIANTS[yoyoBody.plugin?.variantKey || 'standard'];
81	    drawRat(yoyoBody, v, hpFraction);
82	  }
83	
84	  if (aimPoints && aimPoints.length > 1) drawAimGuide(aimPoints);
85	
86	  Particles.draw(ctx);
87	
88	  drawSpeedMeter(angularSpeed);
89	  if (mode === 'swing' || stringConstraint) drawPivotHand(pivot, state);
90	  if (mode === 'push') {
91	    drawHpBar(hpFraction);
92	    drawHitCounter(hitCount);
93	    drawCombo(comboCount);
94	  }
95	  if (hitLabel && hitLabel.alpha > 0) drawHitLabel(hitLabel);
96	  ctx.restore();
97	}
98	
99	function drawBackground(level) {
100	  const key = level.background[0] + '|' + level.background[1];
101	  if (!cachedGradient || cachedGradientKey !== key) {
102	    cachedGradient = ctx.createLinearGradient(0, 0, 0, canvasH);
103	    cachedGradient.addColorStop(0, level.background[0]);
104	    cachedGradient.addColorStop(1, level.background[1]);
105	    cachedGradientKey = key;
106	  }
107	  ctx.fillStyle = cachedGradient;
108	  ctx.fillRect(0, 0, canvasW, canvasH);
109	}
110	
111	function drawGround(level) {
112	  const key = level.groundColor + '|' + canvasW;
113	  if (!cachedGroundCanvas || cachedGroundKey !== key) {
114	    const GRASS_MAX = 9, GROUND_H = 40;
115	    const oc = document.createElement('canvas');
116	    oc.width = canvasW;
117	    oc.height = GRASS_MAX + GROUND_H;
118	    const gctx = oc.getContext('2d');
119	
120	    gctx.fillStyle = level.groundColor;
121	    gctx.fillRect(0, GRASS_MAX, canvasW, GROUND_H);
122	
123	    gctx.strokeStyle = 'rgba(0,0,0,0.5)';
124	    gctx.lineWidth = 3;
125	    gctx.beginPath();
126	    gctx.moveTo(0, GRASS_MAX);
127	    gctx.lineTo(canvasW, GRASS_MAX);
128	    gctx.stroke();
129	
130	    gctx.fillStyle = '#3a8f3a';
131	    for (let x = 10; x < canvasW; x += 22) {
132	      const h = 6 + Math.sin(x * 0.3) * 3;
133	      gctx.fillRect(x, GRASS_MAX - h, 4, h);
134	    }
135	
136	    cachedGroundCanvas = oc;
137	    cachedGroundKey = key;
138	  }
139	  ctx.drawImage(cachedGroundCanvas, 0, canvasH - 49);
140	}
141	
142	function drawString(pivot, yoyo, normalizedSpeed, constraint) {
143	  if (!yoyo) return;
144	  const px = pivot.x, py = pivot.y;
145	  const ex = yoyo.position.x, ey = yoyo.position.y;
146	
147	  const dx = ex - px;
148	  const dy = ey - py;
149	  const dist = Math.sqrt(dx * dx + dy * dy);
150	  if (dist < 1) return;
151	
152	  const perpX = -dy / dist;
153	  const perpY = dx / dist;
154	
155	  // Gravity sag: stronger when rope is horizontal, zero when vertical
156	  const horizontalFraction = Math.abs(dx) / dist;
157	  const gravSag = horizontalFraction * dist * 0.18;
158	
159	  // Extra sag when rope is slack (yoyo closer than constraint length)
160	  const slack = Math.max(0, (constraint?.length ?? dist) - dist);
161	  const slackSag = slack * 0.4;
162	
163	  const totalSag = gravSag + slackSag;
164	
165	  // Lateral bow from swing speed
166	  const speedBow = normalizedSpeed * 16;
167	
168	  // Build 8 rope points with parabolic gravity + speed bow
169	  const N = 8;
170	  const pts = [];
171	  for (let i = 0; i <= N; i++) {
172	    const t = i / N;
173	    const s = Math.sin(t * Math.PI); // 0 at ends, peak at midpoint
174	    pts.push({
175	      x: px + dx * t + perpX * speedBow * s,
176	      y: py + dy * t + perpY * speedBow * s + totalSag * s,
177	    });
178	  }
179	
180	  // Draw smooth curve through points (Catmull-Rom style via quadratic beziers)
181	  ctx.shadowColor = 'rgba(0,0,0,0.25)';
182	  ctx.shadowBlur = 3;
183	  ctx.strokeStyle = '#3d2b1f';
184	  ctx.lineWidth = 2.5;
185	  ctx.lineCap = 'round';
186	  ctx.lineJoin = 'round';
187	  ctx.beginPath();
188	  ctx.moveTo(pts[0].x, pts[0].y);
189	  for (let i = 1; i < pts.length - 1; i++) {
190	    const mx = (pts[i].x + pts[i + 1].x) / 2;
191	    const my = (pts[i].y + pts[i + 1].y) / 2;
192	    ctx.quadraticCurveTo(pts[i].x, pts[i].y, mx, my);
193	  }
194	  ctx.lineTo(pts[pts.length - 1].x, pts[pts.length - 1].y);
195	  ctx.stroke();
196	  ctx.shadowBlur = 0;
197	}
198	
199	function drawTrail(yoyo, level) {
200	  if (!yoyo || trail.length < 2) return;
201	  const v = YOYO_VARIANTS[yoyo.plugin?.variantKey || 'standard'];
202	  for (let i = 1; i < trail.length; i++) {
203	    const alpha = (i / trail.length) * 0.45;
204	    const r = v.radius * (i / trail.length) * 0.7;
205	    ctx.beginPath();
206	    ctx.arc(trail[i].x, trail[i].y, Math.max(1, r), 0, Math.PI * 2);
207	    ctx.fillStyle = v.trailColor + alpha + ')';
208	    ctx.fill();
209	  }
210	}
211	
212	function drawRat(body, variant, hpFraction) {
213	  const { x, y } = body.position;
214	  const r = variant.radius;
215	  ctx.save();
216	  ctx.translate(x, y);
217	  ctx.rotate(spinAngle);
218	
219	  // Body
220	  ctx.shadowColor = 'rgba(0,0,0,0.4)';
221	  ctx.shadowBlur = 8;
222	  ctx.shadowOffsetY = 3;
223	  ctx.beginPath();
224	  ctx.ellipse(0, 0, r * 0.92, r * 0.65, 0, 0, Math.PI * 2);
225	  ctx.fillStyle = variant.color;
226	  ctx.fill();
227	  ctx.shadowBlur = 0;
228	  ctx.shadowOffsetY = 0;
229	  ctx.strokeStyle = variant.outlineColor;
230	  ctx.lineWidth = 2.5;
231	  ctx.stroke();
232	
233	  // Belly highlight
234	  ctx.beginPath();
235	  ctx.ellipse(r * 0.05, r * 0.14, r * 0.44, r * 0.27, 0, 0, Math.PI * 2);
236	  ctx.fillStyle = variant.trimColor;
237	  ctx.fill();
238	
239	  // Head (right side)
240	  const hx = r * 0.68, hy = -r * 0.08, hr = r * 0.46;
241	  ctx.beginPath();
242	  ctx.arc(hx, hy, hr, 0, Math.PI * 2);
243	  ctx.fillStyle = variant.color;
244	  ctx.fill();
245	  ctx.strokeStyle = variant.outlineColor;
246	  ctx.lineWidth = 2;
247	  ctx.stroke();
248	
249	  // Ears
250	  for (const [ex, ey, er] of [
251	    [hx - r * 0.12, hy - hr * 0.85, r * 0.22],
252	    [hx + r * 0.22, hy - hr * 0.72, r * 0.18],
253	  ]) {
254	    ctx.beginPath();
255	    ctx.arc(ex, ey, er, 0, Math.PI * 2);
256	    ctx.fillStyle = variant.color;
257	    ctx.fill();
258	    ctx.strokeStyle = variant.outlineColor;
259	    ctx.lineWidth = 1.5;
260	    ctx.stroke();
261	    ctx.beginPath();
262	    ctx.arc(ex, ey, er * 0.58, 0, Math.PI * 2);
263	    ctx.fillStyle = variant.earColor;
264	    ctx.fill();
265	  }
266	
267	  // Eye
268	  const eyeX = hx + r * 0.2, eyeY = hy - r * 0.13;
269	  if (hpFraction <= 0.25) {
270	    const xs = r * 0.11;
271	    ctx.strokeStyle = '#dd0000';
272	    ctx.lineWidth = 2.5;
273	    ctx.lineCap = 'round';
274	    ctx.beginPath();
275	    ctx.moveTo(eyeX - xs, eyeY - xs); ctx.lineTo(eyeX + xs, eyeY + xs);
276	    ctx.moveTo(eyeX + xs, eyeY - xs); ctx.lineTo(eyeX - xs, eyeY + xs);
277	    ctx.stroke();
278	  } else {
279	    ctx.beginPath();
280	    ctx.arc(eyeX, eyeY, r * 0.1, 0, Math.PI * 2);
281	    ctx.fillStyle = '#111';
282	    ctx.fill();
283	    ctx.beginPath();
284	    ctx.arc(eyeX + r * 0.04, eyeY - r * 0.04, r * 0.04, 0, Math.PI * 2);
285	    ctx.fillStyle = 'rgba(255,255,255,0.7)';
286	    ctx.fill();
287	  }
288	
289	  // Snout
290	  const sx = hx + hr * 0.82, sy = hy + r * 0.05;
291	  ctx.beginPath();
292	  ctx.ellipse(sx, sy, r * 0.14, r * 0.1, 0.2, 0, Math.PI * 2);
293	  ctx.fillStyle = variant.snoutColor;
294	  ctx.fill();
295	  ctx.beginPath();
296	  ctx.arc(sx + r * 0.08, sy, r * 0.065, 0, Math.PI * 2);
297	  ctx.fillStyle = '#111';
298	  ctx.fill();
299	
300	  // Whiskers
301	  ctx.lineCap = 'round';
302	  for (let i = -1; i <= 1; i++) {
303	    const wy = sy + i * r * 0.1;
304	    ctx.strokeStyle = `rgba(220,215,200,${0.85 - Math.abs(i) * 0.2})`;
305	    ctx.lineWidth = 1;
306	    ctx.beginPath();
307	    ctx.moveTo(sx, wy);
308	    ctx.lineTo(sx + r * 0.52, wy + i * r * 0.12 - r * 0.05);
309	    ctx.stroke();
310	    ctx.beginPath();
311	    ctx.moveTo(sx, wy);
312	    ctx.lineTo(sx - r * 0.18, wy - i * r * 0.07);
313	    ctx.stroke();
314	  }
315	
316	  // Tail
317	  ctx.beginPath();
318	  ctx.moveTo(-r * 0.85, r * 0.22);
319	  ctx.bezierCurveTo(-r * 1.15, r * 0.58, -r * 1.55, -r * 0.22, -r * 1.82, r * 0.12);
320	  ctx.strokeStyle = variant.tailColor;
321	  ctx.lineWidth = 2.5;
322	  ctx.lineCap = 'round';
323	  ctx.stroke();
324	
325	  // Damage state overlays
326	  if (hpFraction < 0.75) drawRatDamage(hpFraction, hx, hy - hr * 0.6, r);
327	
328	  ctx.restore();
329	}
330	
331	function drawRatDamage(hpFraction, headX, headTopY, r) {
332	  const t = Date.now() / 500;
333	  if (hpFraction >= 0.5) {
334	    // Dazed: golden orbiting stars
335	    for (let i = 0; i < 3; i++) {
336	      const a = t + (i * Math.PI * 2 / 3);
337	      ctx.fillStyle = '#FFD700';
338	      ctx.font = `${Math.ceil(r * 0.5)}px system-ui`;
339	      ctx.textAlign = 'center';
340	      ctx.textBaseline = 'middle';
341	      ctx.fillText('★', headX + Math.cos(a) * r * 0.55, headTopY + Math.sin(a) * r * 0.25);
342	    }
343	    ctx.textBaseline = 'alphabetic';
344	  } else {
345	    // Injured / Critical: wound marks + blood drips
346	    const woundCount = hpFraction < 0.25 ? 4 : 2;
347	    const woundPositions = [
348	      [-r * 0.35, -r * 0.18],
349	      [r * 0.06, r * 0.28],
350	      [-r * 0.52, r * 0.12],
351	      [r * 0.22, -r * 0.32],
352	    ];
353	    ctx.strokeStyle = '#cc2222';
354	    ctx.lineWidth = 1.8;
355	    ctx.lineCap = 'round';
356	    for (let i = 0; i < woundCount; i++) {
357	      const [wx, wy] = woundPositions[i];
358	      const s = r * 0.14;
359	      ctx.beginPath();
360	      ctx.moveTo(wx - s, wy - s * 0.4); ctx.lineTo(wx + s, wy + s * 0.4);
361	      ctx.moveTo(wx - s * 0.4, wy - s); ctx.lineTo(wx + s * 0.4, wy + s);
362	      ctx.stroke();
363	    }
364	
365	    // Blood drips — in local space so they fling outward as the rat spins
366	    const dripPositions = hpFraction < 0.25
367	      ? [[-r*0.28, r*0.58, r*0.42], [r*0.12, r*0.62, r*0.32], [-r*0.58, r*0.42, r*0.28], [r*0.32, r*0.54, r*0.38]]
368	      : [[-r*0.28, r*0.58, r*0.22], [r*0.12, r*0.62, r*0.18]];
369	    ctx.fillStyle = '#aa0000';
370	    for (const [dx, dy, len] of dripPositions) {
371	      const dr = r * 0.075;
372	      ctx.beginPath();
373	      ctx.arc(dx, dy, dr, 0, Math.PI * 2);
374	      ctx.fill();
375	      ctx.beginPath();
376	      ctx.moveTo(dx - dr * 0.9, dy);
377	      ctx.lineTo(dx + dr * 0.9, dy);
378	      ctx.lineTo(dx, dy + len);
379	      ctx.closePath();
380	      ctx.fill();
381	    }
382	
383	    // Critical: red spinning stars too
384	    if (hpFraction < 0.25) {
385	      const tf = Date.now() / 380;
386	      for (let i = 0; i < 3; i++) {
387	        const a = tf + (i * Math.PI * 2 / 3);
388	        ctx.fillStyle = '#FF3333';
389	        ctx.font = `${Math.ceil(r * 0.5)}px system-ui`;
390	        ctx.textAlign = 'center';
391	        ctx.textBaseline = 'middle';
392	        ctx.fillText('★', headX + Math.cos(a) * r * 0.55, headTopY + Math.sin(a) * r * 0.25);
393	      }
394	      ctx.textBaseline = 'alphabetic';
395	    }
396	  }
397	}
398	
399	function drawTargets(targets) {
400	  for (const body of targets) {
401	    const mat = MATERIALS[body.plugin.materialKey];
402	    drawPhysicsBody(body, body.plugin.cracked ? mat.crackedColor : mat.color, mat.outlineColor);
403	    if (body.plugin.cracked && body.plugin.crackPattern) drawCracks(body, body.plugin.crackPattern);
404	
405	    // material label
406	    const { x, y } = body.position;
407	    ctx.fillStyle = 'rgba(0,0,0,0.5)';
408	    ctx.font = 'bold 11px system-ui';
409	    ctx.textAlign = 'center';
410	    ctx.fillText(mat.label, x, y + 4);
411	
412	    // glow
413	    ctx.save();
414	    ctx.globalAlpha = 0.18;
415	    ctx.beginPath();
416	    const verts = body.vertices;
417	    ctx.moveTo(verts[0].x, verts[0].y);
418	    for (let i = 1; i < verts.length; i++) ctx.lineTo(verts[i].x, verts[i].y);
419	    ctx.closePath();
420	    ctx.fillStyle = mat.glowColor;
421	    ctx.fill();
422	    ctx.restore();
423	
424	  }
425	}
426	
427	function drawCracks(body, pattern) {
428	  const { x, y } = body.position;
429	  const w = body.plugin.width;
430	  const h = body.plugin.height;
431	  const maxR = Math.min(w, h) * 0.45;
432	  ctx.save();
433	  ctx.translate(x, y);
434	  ctx.rotate(body.angle);
435	  ctx.strokeStyle = 'rgba(0,0,0,0.55)';
436	  ctx.lineWidth = 1.5;
437	  for (const { angle, len } of pattern) {
438	    ctx.beginPath();
439	    ctx.moveTo(0, 0);
440	    ctx.lineTo(Math.cos(angle) * len * maxR * 2, Math.sin(angle) * len * maxR * 2);
441	    ctx.stroke();
442	  }
443	  ctx.restore();
444	}
445	
446	const GIBLET_COLORS = ['#cc0000', '#ff1111', '#ff3333', '#dd0000', '#ff4444'];
447	
448	function drawFragments(frags) {
449	  const now = Date.now();
450	  for (const body of frags) {
451	    const age = (now - body.plugin.born) / 4000;
452	    const alpha = Math.max(0, 1 - age);
453	    const r = (body.circleRadius || 6) * 2.2;
454	    const ci = Math.abs(Math.round(body.position.x * 7 + body.position.y * 3)) % GIBLET_COLORS.length;
455	    ctx.globalAlpha = alpha;
456	    ctx.save();
457	    ctx.translate(body.position.x, body.position.y);
458	    ctx.rotate(body.angle);
459	    ctx.beginPath();
460	    ctx.ellipse(0, 0, r, r * 0.55, 0, 0, Math.PI * 2);
461	    ctx.fillStyle = GIBLET_COLORS[ci];
462	    ctx.fill();
463	    ctx.strokeStyle = '#660000';
464	    ctx.lineWidth = 2;
465	    ctx.stroke();
466	    ctx.restore();
467	    ctx.globalAlpha = 1;
468	  }
469	}
470	
471	function drawPhysicsBody(body, fill, stroke) {
472	  const verts = body.vertices;
473	  ctx.beginPath();
474	  ctx.moveTo(verts[0].x, verts[0].y);
475	  for (let i = 1; i < verts.length; i++) ctx.lineTo(verts[i].x, verts[i].y);
476	  ctx.closePath();
477	
478	  ctx.shadowColor = 'rgba(0,0,0,0.2)';
479	  ctx.shadowBlur = 6;
480	  ctx.fillStyle = fill;
481	  ctx.fill();
482	  ctx.shadowBlur = 0;
483	
484	  ctx.strokeStyle = stroke;
485	  ctx.lineWidth = 3;
486	  ctx.lineJoin = 'round';
487	  ctx.stroke();
488	}
489	
490	function drawAimGuide(points) {
491	  ctx.save();
492	  ctx.setLineDash([6, 8]);
493	  ctx.strokeStyle = 'rgba(255,255,200,0.45)';
494	  ctx.lineWidth = 2;
495	  ctx.beginPath();
496	  ctx.moveTo(points[0].x, points[0].y);
497	  for (let i = 1; i < points.length; i++) ctx.lineTo(points[i].x, points[i].y);
498	  ctx.stroke();
499	  ctx.setLineDash([]);
500	  ctx.restore();
501	}
502	
503	function drawSpeedMeter(normalizedSpeed) {
504	  const cx = 60, cy = canvasH - 55, r = 38;
505	  const startAngle = Math.PI;
506	  const endAngle = Math.PI * 2;
507	
508	  // bg arc
509	  ctx.beginPath();
510	  ctx.arc(cx, cy, r, startAngle, endAngle);
511	  ctx.strokeStyle = 'rgba(0,0,0,0.35)';
512	  ctx.lineWidth = 10;
513	  ctx.lineCap = 'round';
514	  ctx.stroke();
515	
516	  // fill arc
517	  const fillEnd = startAngle + normalizedSpeed * Math.PI;
518	  const hue = 120 - normalizedSpeed * 120; // green→red
519	  ctx.beginPath();
520	  ctx.arc(cx, cy, r, startAngle, fillEnd);
521	  ctx.strokeStyle = `hsl(${hue},90%,50%)`;
522	  ctx.lineWidth = 10;
523	  ctx.stroke();
524	
525	  // needle
526	  const needleAngle = startAngle + normalizedSpeed * Math.PI;
527	  ctx.beginPath();
528	  ctx.moveTo(cx, cy);
529	  ctx.lineTo(cx + Math.cos(needleAngle) * (r - 4), cy + Math.sin(needleAngle) * (r - 4));
530	  ctx.strokeStyle = 'white';
531	  ctx.lineWidth = 2.5;
532	  ctx.stroke();
533	
534	  // label
535	  ctx.fillStyle = 'rgba(255,255,255,0.7)';
536	  ctx.font = 'bold 10px system-ui';
537	  ctx.textAlign = 'center';
538	  ctx.fillText('SPIN', cx, cy + 14);
539	}
540	
541	function drawPivotHand(pivot, state) {
542	  // Draw a simple hand/anchor indicator
543	  ctx.save();
544	  ctx.translate(pivot.x, pivot.y);
545	
546	  ctx.beginPath();
547	  ctx.arc(0, 0, 10, 0, Math.PI * 2);
548	  ctx.fillStyle = state === 'SWINGING' ? '#f9c74f' : 'rgba(255,255,255,0.5)';
549	  ctx.fill();
550	  ctx.strokeStyle = '#333';
551	  ctx.lineWidth = 2.5;
552	  ctx.stroke();
553	
554	  // little grip lines
555	  for (let i = 0; i < 3; i++) {
556	    const y = -3 + i * 3;
557	    ctx.beginPath();
558	    ctx.moveTo(-5, y);
559	    ctx.lineTo(5, y);
560	    ctx.strokeStyle = 'rgba(0,0,0,0.4)';
561	    ctx.lineWidth = 1.5;
562	    ctx.stroke();
563	  }
564	
565	  ctx.restore();
566	}
567	
568	function drawHpBar(fraction) {
569	  const barW = 160;
570	  const barH = 12;
571	  const x = canvasW - barW - 20;
572	  const y = canvasH - 68;
573	
574	  ctx.fillStyle = 'rgba(0,0,0,0.4)';
575	  ctx.fillRect(x, y, barW, barH);
576	
577	  const hue = fraction * 120; // green → red as HP drops
578	  ctx.fillStyle = `hsl(${hue},85%,50%)`;
579	  ctx.fillRect(x, y, barW * Math.max(0, fraction), barH);
580	
581	  ctx.strokeStyle = 'rgba(255,255,255,0.25)';
582	  ctx.lineWidth = 1;
583	  ctx.strokeRect(x, y, barW, barH);
584	
585	  ctx.fillStyle = 'rgba(255,255,255,0.65)';
586	  ctx.font = 'bold 10px system-ui';
587	  ctx.textAlign = 'right';
588	  ctx.fillText('HP', x - 6, y + barH - 1);
589	  ctx.textAlign = 'left';
590	}
591	
592	function drawHitCounter(hitCount) {
593	  ctx.fillStyle = 'rgba(255,255,255,0.65)';
594	  ctx.font = 'bold 12px system-ui';
595	  ctx.textAlign = 'right';
596	  ctx.fillText(`Hits: ${hitCount}`, canvasW - 20, canvasH - 82);
597	  ctx.textAlign = 'left';
598	}
599	
600	function drawHitLabel({ text, x, y, alpha, color }) {
601	  ctx.globalAlpha = Math.max(0, alpha);
602	  ctx.fillStyle = color;
603	  ctx.font = 'bold 18px system-ui';
604	  ctx.textAlign = 'center';
605	  ctx.fillText(text, x, y - 30);
606	  ctx.textAlign = 'left';
607	  ctx.globalAlpha = 1;
608	}
609	
610	function drawCombo(combo) {
611	  if (combo < 2) return;
612	  const mult = Math.min(1 + (combo - 1) * 0.5, 3.0).toFixed(1);
613	  const hue = Math.max(0, 60 - (combo - 2) * 15); // yellow → orange → red
614	  ctx.fillStyle = `hsl(${hue}, 100%, 60%)`;
615	  ctx.font = `bold ${14 + Math.min(combo, 5) * 2}px system-ui`;
616	  ctx.textAlign = 'right';
617	  ctx.fillText(`${combo}× COMBO  ${mult}x`, canvasW - 20, canvasH - 96);
618	  ctx.textAlign = 'left';
619	}
