body {
  background: #1a1a2e;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  font-family: 'Segoe UI', system-ui, sans-serif;
  overflow: hidden;
}

#game-container {
  position: relative;
  user-select: none;
}

#game-canvas {
  display: block;
  border-radius: 12px;
  box-shadow: 0 0 40px rgba(0,0,0,0.6);
  cursor: crosshair;
}

/* Yoyo picker */
#yoyo-picker {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  background: rgba(0,0,0,0.55);
  border-radius: 50px;
  padding: 10px 18px;
  backdrop-filter: blur(8px);
  border: 2px solid rgba(255,255,255,0.15);
}

.picker-label {
  color: rgba(255,255,255,0.7);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.5px;
  white-space: nowrap;
}

.yoyo-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  background: rgba(255,255,255,0.08);
  border: 2px solid rgba(255,255,255,0.2);
  border-radius: 12px;
  padding: 8px 14px;
  cursor: pointer;
  transition: all 0.18s ease;
  color: white;
}

.yoyo-btn:hover {
  background: rgba(255,255,255,0.16);
  border-color: rgba(255,255,255,0.4);
}

.yoyo-btn.active {
  background: rgba(255,255,255,0.22);
  border-color: #f9c74f;
  box-shadow: 0 0 12px rgba(249,199,79,0.3);
}

.yoyo-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: block;
  border: 3px solid rgba(0,0,0,0.35);
}

.standard-icon { background: #e63946; }
.heavy-icon { background: #343a40; border-color: #868e96; }

.yoyo-name {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.3px;
}

.yoyo-desc {
  font-size: 10px;
  color: rgba(255,255,255,0.55);
}

.picker-sep {
  width: 1px;
  height: 36px;
  background: rgba(255,255,255,0.2);
  margin: 0 4px;
}

.mode-btn {
  background: rgba(255,255,255,0.08);
  border: 2px solid rgba(255,255,255,0.2);
  border-radius: 10px;
  padding: 8px 14px;
  cursor: pointer;
  color: white;
  font-size: 12px;
  font-weight: 700;
  transition: all 0.18s ease;
  letter-spacing: 0.3px;
}

.mode-btn:hover {
  background: rgba(255,255,255,0.16);
  border-color: rgba(255,255,255,0.4);
}

.mode-btn.active {
  background: rgba(255,255,255,0.22);
  border-color: #90e0ef;
  box-shadow: 0 0 12px rgba(144,224,239,0.3);
}

.start-btn {
  background: linear-gradient(135deg, #f9c74f, #f8961e);
  border: none;
  border-radius: 22px;
  padding: 10px 22px;
  font-size: 15px;
  font-weight: 800;
  color: #1a1a1a;
  cursor: pointer;
  transition: transform 0.15s, box-shadow 0.15s;
  box-shadow: 0 4px 14px rgba(248,150,30,0.4);
  letter-spacing: 0.5px;
}

.start-btn:hover {
  transform: scale(1.06);
  box-shadow: 0 6px 20px rgba(248,150,30,0.55);
}

.start-btn:active { transform: scale(0.97); }

/* Hint text */
#hint-text {
  position: absolute;
  bottom: 110px;
  left: 50%;
  transform: translateX(-50%);
  color: rgba(255,255,255,0.6);
  font-size: 13px;
  font-style: italic;
  pointer-events: none;
  text-align: center;
  white-space: nowrap;
}

/* Result panel */
#result-panel {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(10,10,20,0.88);
  border-radius: 20px;
  border: 2px solid rgba(255,255,255,0.15);
  backdrop-filter: blur(12px);
  padding: 32px 48px;
  text-align: center;
  color: white;
  min-width: 280px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.6);
  animation: slideIn 0.3s cubic-bezier(0.34,1.56,0.64,1);
}

@keyframes slideIn {
  from { transform: translate(-50%, -60%); opacity: 0; }
  to   { transform: translate(-50%, -50%); opacity: 1; }
}

#result-panel.hidden { display: none; }

#result-outcome {
  font-size: 32px;
  font-weight: 900;
  letter-spacing: 1px;
  margin-bottom: 8px;
}

.outcome-shatter { color: #f9c74f; text-shadow: 0 0 20px rgba(249,199,79,0.5); }
.outcome-crack   { color: #90e0ef; }
.outcome-survive { color: #adb5bd; }

#result-stars {
  font-size: 28px;
  margin-bottom: 12px;
  letter-spacing: 4px;
}

#result-score-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: rgba(255,255,255,0.45);
  margin-bottom: 2px;
}

#result-score {
  font-size: 48px;
  font-weight: 900;
  color: #f9c74f;
  line-height: 1;
  margin-bottom: 20px;
}

#result-buttons {
  display: flex;
  gap: 10px;
  justify-content: center;
}

#result-buttons button {
  padding: 10px 26px;
  border-radius: 22px;
  border: none;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.15s, box-shadow 0.15s;
}

#retry-btn {
  background: rgba(255,255,255,0.12);
  color: white;
  border: 2px solid rgba(255,255,255,0.25);
}

#retry-btn:hover { background: rgba(255,255,255,0.2); }

#next-btn {
  background: linear-gradient(135deg, #f9c74f, #f8961e);
  color: #1a1a1a;
  box-shadow: 0 4px 14px rgba(248,150,30,0.35);
}

#next-btn:hover { transform: scale(1.05); }
#next-btn.hidden { display: none; }

/* Level select */
#level-select {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(15, 15, 30, 0.94);
  border: 1px solid rgba(255,255,255,0.12);
